<?php declare(strict_types=1); use FastWebsite\Core\View;
$mediaUrl=static function(mixed$path)use($baseUrl):?string{if(!is_string($path)||trim($path)===''||preg_match('#^(?:https?:)?//#i',$path)===1)return null;return$baseUrl.ltrim(preg_replace('#^public/#','',str_replace('\\','/',$path))??$path,'/');}; ?>
<section class="page-heading department-heading"><div class="shell"><p class="eyebrow"><?=View::escape(View::setting($siteContent??[],'research.eyebrow','Discovery and innovation'))?></p><h1><?=View::escape(View::setting($siteContent??[],'research.title','Research at FAST'))?></h1><p class="lead"><?=View::escape(View::setting($siteContent??[],'research.introduction','Explore our research centres, laboratories, groups, expertise, and opportunities.'))?></p><div class="heading-actions"><a class="button button-primary" href="<?=View::escape($baseUrl)?>research/projects"><?=View::escape(View::setting($siteContent??[],'research.projects_title','Research projects'))?></a><a class="button button-secondary" href="<?=View::escape($baseUrl)?>research/publications"><?=View::escape(View::setting($siteContent??[],'research.publications_title','Research publications'))?></a></div></div></section>
<section class="section"><div class="shell"><form class="public-search" method="get" action="<?=View::escape($baseUrl)?>research"><label for="research-directory-search">Find a research unit</label><div><input id="research-directory-search" name="q" type="search" maxlength="100" value="<?=View::escape($search)?>" placeholder="Name, acronym, or focus"><select name="type" aria-label="Research unit type"><option value="">All unit types</option><?php foreach($types as$type):?><option value="<?=View::escape($type['code'])?>"<?=$typeFilter===$type['code']?' selected':''?>><?=View::escape($type['name'])?></option><?php endforeach;?></select><button class="button button-primary" type="submit">Search</button></div></form>
<?php if($result['items']===[]):?><div class="public-empty"><h2><?=$search===''&&$typeFilter===''?View::escape(View::setting($siteContent??[],'research.empty','Research pages are being prepared')):'No research units found'?></h2><p>Published research units will appear here.</p></div><?php else:?><div class="department-card-grid"><?php foreach($result['items']as$unit):?><?php $image=$mediaUrl($unit['hero_path']);?><article class="department-card"><?php if($image):?><img src="<?=View::escape($image)?>" alt="<?=View::escape($unit['hero_alt_text']?:$unit['name'])?>"><?php endif;?><div><p class="eyebrow"><?=View::escape($unit['type_name'])?></p><h2><a href="<?=View::escape($baseUrl)?>research/<?=View::escape($unit['slug'])?>"><?=View::escape($unit['name'])?></a></h2><p><?=View::escape(mb_strimwidth((string)($unit['overview']?:$unit['research_focus']),0,190,'…'))?></p><p class="card-meta"><?=View::escape(implode(' · ',array_filter([$unit['acronym'],$unit['department_name']])))?></p><a class="text-link" href="<?=View::escape($baseUrl)?>research/<?=View::escape($unit['slug'])?>">Explore research →</a></div></article><?php endforeach;?></div><?php endif;?></div></section>
